CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requested_role public.user_role;
  new_vendor_id uuid;
  business_name text;
  business_category text;
begin
  if coalesce(new.raw_user_meta_data->>'role','customer') not in ('customer','vendor') then
    raise exception 'Only customer or vendor registration is allowed';
  end if;
  requested_role := coalesce(new.raw_user_meta_data->>'role','customer')::public.user_role;
  business_name := nullif(trim(new.raw_user_meta_data->>'business_name'),'');
  business_category := nullif(trim(new.raw_user_meta_data->>'business_category'),'');
  if requested_role = 'vendor' and (business_name is null or business_category is null) then
    raise exception 'Business name and category are required';
  end if;
  insert into public.profiles(id,name,email,role,building)
  values(new.id,coalesce(nullif(trim(new.raw_user_meta_data->>'name'),''),split_part(new.email,'@',1)),
    new.email,requested_role,nullif(trim(new.raw_user_meta_data->>'building'),''));
  if requested_role='vendor' then
    insert into public.vendors(owner_id,name,category,building,status,email)
    values(new.id,business_name,business_category,nullif(trim(new.raw_user_meta_data->>'building'),''),'pending',new.email)
    returning id into new_vendor_id;
    update public.profiles set vendor_id=new_vendor_id where id=new.id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.submit_payment_proof(p_order_id uuid, p_proof_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order orders;
begin
  select * into v_order from orders where id = p_order_id;

  if v_order.id is null then
    raise exception 'Order not found';
  end if;

  if v_order.customer_id is not null and v_order.customer_id is distinct from auth.uid() then
    raise exception 'Not authorized for this order';
  end if;

  if v_order.status <> 'pending_payment' then
    raise exception 'This order is not awaiting payment';
  end if;

  update orders
    set payment_proof_url = p_proof_path, status = 'payment_submitted'
    where id = p_order_id;

  update order_suborders
    set status = 'payment_submitted', payment_status = 'verifying'
    where order_id = p_order_id;

  return (select order_to_json(o) from orders o where o.id = p_order_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_suborder_status_and_notify(p_order_id uuid, p_next_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_vendor_id uuid := private.current_vendor_id();
  v_sub public.order_suborders%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_next public.order_status;
  v_parent public.order_status;
  v_vendor_name text;
  v_old_step integer;
  v_new_step integer;
BEGIN
  IF auth.uid() IS NULL OR v_vendor_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized: current user is not a vendor';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.vendors v JOIN public.profiles p ON p.id=auth.uid()
      WHERE v.id=v_vendor_id AND v.owner_id=auth.uid() AND v.status='approved'
      AND p.role='vendor' AND NOT p.suspended) THEN
    RAISE EXCEPTION 'An approved, active vendor account is required';
  END IF;
  -- All payment/status operations lock the parent first to serialize updates.
  SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE;
  SELECT * INTO v_sub FROM public.order_suborders
    WHERE order_id=p_order_id AND vendor_id=v_vendor_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Suborder not found for this vendor'; END IF;
  IF v_sub.payment_status <> 'paid' OR v_order.status NOT IN ('confirmed','accepted','preparing','ready','collected','completed') THEN
    RAISE EXCEPTION 'Payment must be verified before advancing an order';
  END IF;
  IF p_next_status IS NULL OR p_next_status NOT IN ('accepted','preparing','ready','collected','completed') THEN
    RAISE EXCEPTION 'Vendors may only advance fulfilment; payment confirmation is server-controlled';
  END IF;
  v_next := p_next_status::public.order_status;
  SELECT step INTO v_old_step FROM public.order_flow WHERE status=v_sub.status;
  SELECT step INTO v_new_step FROM public.order_flow WHERE status=v_next;
  IF v_old_step IS NULL OR v_new_step IS NULL OR v_new_step<>v_old_step+1 THEN
    RAISE EXCEPTION 'Invalid status transition: % -> %',v_sub.status,v_next;
  END IF;
  UPDATE public.order_suborders SET status=v_next WHERE id=v_sub.id;
  -- The parent represents the least advanced vendor, even when vendors progress separately.
  SELECT so.status INTO v_parent FROM public.order_suborders so
    JOIN public.order_flow f ON f.status=so.status
    WHERE so.order_id=p_order_id ORDER BY f.step LIMIT 1;
  IF v_parent IS NOT NULL AND v_parent IS DISTINCT FROM v_order.status THEN
    UPDATE public.orders SET status=v_parent WHERE id=p_order_id;
  END IF;
  SELECT name INTO v_vendor_name FROM public.vendors WHERE id=v_vendor_id;
  IF v_order.customer_id IS NOT NULL THEN
    INSERT INTO public.notifications(user_id,type,title,body,action_url)
    VALUES(v_order.customer_id,'order_status',
      CASE p_next_status WHEN 'accepted' THEN 'Order accepted' WHEN 'preparing' THEN 'Order is being prepared'
        WHEN 'ready' THEN 'Order ready for collection' WHEN 'collected' THEN 'Order collected' ELSE 'Order completed' END,
      format('%s: %s (%s)',v_vendor_name,initcap(replace(p_next_status,'_',' ')),v_order.ticket_number),
      '/orders/'||p_order_id::text);
  END IF;
  RETURN jsonb_build_object('success',true,'status',v_next);
END $function$

CREATE OR REPLACE FUNCTION public.create_order_from_cart(p_customer_id uuid, p_guest_name text, p_guest_contact text, p_guest_email text, p_delivery_date date, p_delivery_location text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_customer_id uuid := auth.uid();
  v_order_id uuid := gen_random_uuid();
  v_ticket text;
  v_total numeric(10,2);
  v_requested_count integer;
  v_priced_count integer;
  v_vendor_id uuid;
  v_suborder_id uuid;
begin
  if p_customer_id is not null and p_customer_id is distinct from auth.uid() then
    raise exception 'Customer identity does not match the current session';
  end if;

  if v_customer_id is not null and exists(select 1 from public.profiles where id=v_customer_id and suspended) then
    raise exception 'This account is suspended';
  end if;

  if v_customer_id is not null then
    p_guest_name := null;
    p_guest_contact := null;
    p_guest_email := null;
  else
    if nullif(trim(p_guest_name), '') is null then
      raise exception 'Guest name is required';
    end if;
    if nullif(trim(p_guest_contact), '') is null then
      raise exception 'Guest mobile number is required';
    end if;
  end if;

  if p_delivery_date is null then
    raise exception 'Delivery date is required';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Your cart is empty';
  end if;

  if nullif(trim(p_delivery_location), '') is null then raise exception 'Delivery location is required'; end if;
  if clock_timestamp() >= (((p_delivery_date - 1)::timestamp + interval '19 hours') at time zone 'Africa/Johannesburg') then
    raise exception 'Ordering has closed for this delivery date';
  end if;
  if exists(select 1 from jsonb_array_elements(p_items) x
    where jsonb_typeof(x) <> 'object' or coalesce(x->>'mealId','') = ''
      or coalesce(x->>'qty','') !~ '^[1-9][0-9]*$') then
    raise exception 'Every cart item requires a meal ID and positive whole-number quantity';
  end if;
  if exists(select 1 from jsonb_array_elements(p_items) x where (x->>'qty')::numeric > 2147483647) then
    raise exception 'Cart quantity is too large';
  end if;
  if (select count(*) <> count(distinct x->>'mealId') from jsonb_array_elements(p_items) x) then
    raise exception 'Combine duplicate meals into one cart item';
  end if;
  perform m.id from jsonb_array_elements(p_items) x
    join public.meals m on m.id=(x->>'mealId')::uuid
    join public.vendors v on v.id=m.vendor_id for share of m,v;

  select count(distinct (x->>'mealId')::uuid)
    into v_requested_count
  from jsonb_array_elements(p_items) x
  where nullif(x->>'mealId', '') is not null;

  if v_requested_count = 0 then
    raise exception 'Your cart contains no valid meals';
  end if;

  select count(distinct m.id)
    into v_priced_count
  from jsonb_array_elements(p_items) x
  join meals m on m.id = (x->>'mealId')::uuid
  join vendors v on v.id = m.vendor_id
  where m.available = true
    and v.status = 'approved'
    and (x->>'qty')::integer > 0
    and (m.available_days is null or cardinality(m.available_days)=0
      or extract(dow from p_delivery_date)::integer=any(m.available_days));

  if v_priced_count <> v_requested_count then
    raise exception 'One or more meals in your cart are no longer available';
  end if;

  select round(sum(m.price * (x->>'qty')::integer), 2)
    into v_total
  from jsonb_array_elements(p_items) x
  join meals m on m.id = (x->>'mealId')::uuid
  join vendors v on v.id = m.vendor_id
  where m.available = true and v.status = 'approved';

  v_ticket := 'OB-' || upper(substr(md5(v_order_id::text || clock_timestamp()::text), 1, 6));

  insert into orders (
    id, ticket_number, customer_id, guest_name, guest_contact, guest_email,
    delivery_date, delivery_location, status, total
  )
  values (
    v_order_id,
    v_ticket,
    v_customer_id,
    case when v_customer_id is null then trim(p_guest_name) else null end,
    case when v_customer_id is null then trim(p_guest_contact) else null end,
    case when v_customer_id is null then nullif(trim(p_guest_email), '') else null end,
    p_delivery_date,
    nullif(trim(p_delivery_location), ''),
    'pending_payment',
    v_total
  );

  for v_vendor_id in
    select m.vendor_id
    from jsonb_array_elements(p_items) x
    join meals m on m.id = (x->>'mealId')::uuid
    join vendors v on v.id = m.vendor_id
    where m.available = true and v.status = 'approved'
    group by m.vendor_id
  loop
    insert into order_suborders (order_id, vendor_id, status, payment_status, subtotal)
    select
      v_order_id,
      v_vendor_id,
      'pending_payment',
      'unpaid',
      round(sum(m.price * (x->>'qty')::integer), 2)
    from jsonb_array_elements(p_items) x
    join meals m on m.id = (x->>'mealId')::uuid
    where m.vendor_id = v_vendor_id
    returning id into v_suborder_id;

    insert into order_items (suborder_id, meal_id, meal_name, qty, price)
    select
      v_suborder_id,
      m.id,
      m.name,
      (x->>'qty')::integer,
      m.price
    from jsonb_array_elements(p_items) x
    join meals m on m.id = (x->>'mealId')::uuid
    where m.vendor_id = v_vendor_id;
  end loop;

  return order_to_json((select o from orders o where o.id = v_order_id));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_verify_payment(p_order_id uuid, p_approve boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order orders;
  v_new_status text;
  v_vendor_id uuid;
  v_vendor_name text;
  v_customer_name text;
  v_items text;
  v_subtotal numeric;
  v_customer_id uuid;
  v_ticket text;
  v_delivery_date date;
  v_delivery_location text;
  v_notify_errors jsonb := '[]'::jsonb;
begin
  if not private.is_admin() then
    raise exception 'Not authorized: admin access required';
  end if;

  select * into v_order from orders where id = p_order_id for update;
  if v_order.id is null then
    raise exception 'Order not found';
  end if;

  if v_order.status not in ('payment_submitted', 'pending_payment') then
    raise exception 'Order is not awaiting payment review (current status: %)', v_order.status;
  end if;

  v_new_status := case when p_approve then 'confirmed' else 'cancelled' end;
  v_customer_id := v_order.customer_id;
  v_ticket := v_order.ticket_number;
  v_delivery_date := v_order.delivery_date;
  v_delivery_location := v_order.delivery_location;

  select coalesce(p.name, v_order.guest_name, 'Guest')
    into v_customer_name
  from (select 1) x
  left join profiles p on p.id = v_order.customer_id;

  update orders set status = v_new_status::order_status where id = p_order_id;

  update order_suborders
    set status = v_new_status::order_status,
        payment_status = case when p_approve then 'paid'::payment_status else 'unpaid'::payment_status end
    where order_id = p_order_id;

  if v_customer_id is not null then
    insert into notifications (user_id, type, title, body)
    values (
      v_customer_id,
      case when p_approve then 'payment_verified' else 'payment_rejected' end,
      case when p_approve then 'Payment verified' else 'Payment rejected' end,
      case when p_approve
        then format('Your payment for %s has been verified — your order is confirmed.', v_ticket)
        else format('We could not verify the payment for %s. Please upload valid proof or contact support.', v_ticket)
      end
    );
  end if;

  if p_approve then
    for v_vendor_id, v_vendor_name, v_subtotal in
      select so.vendor_id, v.name, so.subtotal
      from order_suborders so
      join vendors v on v.id = so.vendor_id
      where so.order_id = p_order_id
    loop
      select coalesce(string_agg(format('%s × %s', oi.qty, oi.meal_name), ', ' order by oi.id), 'No items recorded')
        into v_items
      from order_items oi
      join order_suborders so on so.id = oi.suborder_id
      where so.order_id = p_order_id and so.vendor_id = v_vendor_id;

      for v_customer_id in
        select p.id
        from profiles p
        where p.vendor_id = v_vendor_id and p.role = 'vendor'
      loop
        insert into notifications (user_id, type, title, body)
        values (
          v_customer_id,
          'new_order',
          format('New order %s', v_ticket),
          format(
            'Customer: %s | Items: %s | Vendor subtotal: R%s | Delivery: %s%s',
            v_customer_name,
            v_items,
            to_char(coalesce(v_subtotal, 0), 'FM999999990.00'),
            coalesce(to_char(v_delivery_date, 'DD Mon YYYY'), 'Not specified'),
            case when nullif(trim(v_delivery_location), '') is not null
              then format(' | Location: %s', v_delivery_location)
              else '' end
          )
        );
      end loop;
    end loop;
  end if;

  return jsonb_build_object(
    'success', true,
    'status', v_new_status,
    'notify_errors', v_notify_errors
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.become_vendor(p_business_name text, p_business_category text, p_building text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 current_user_id uuid := auth.uid(); current_profile public.profiles%rowtype; existing_vendor public.vendors%rowtype; new_vendor public.vendors%rowtype;
 clean_name text:=nullif(trim(p_business_name),''); clean_category text:=nullif(trim(p_business_category),''); clean_building text:=nullif(trim(p_building),'');
begin
 if current_user_id is null then raise exception 'You must be signed in to become a vendor'; end if;
 if clean_name is null then raise exception 'Business name is required'; end if;
 if clean_category is null then raise exception 'Business category is required'; end if;
 select * into current_profile from public.profiles where id=current_user_id for update;
 if not found then raise exception 'OfficeBites profile not found'; end if;
 if current_profile.role::text='admin' then raise exception 'Admin accounts cannot be converted to vendor accounts'; end if;
 if current_profile.vendor_id is not null then
  select * into existing_vendor from public.vendors where id=current_profile.vendor_id;
  if found then return jsonb_build_object('vendor_id',existing_vendor.id,'status',existing_vendor.status,'already_vendor',true); end if;
  raise exception 'Profile has an invalid vendor link';
 end if;
 select * into existing_vendor from public.vendors where owner_id=current_user_id order by created_at asc limit 1;
 if found then
  update public.profiles set role='vendor',vendor_id=existing_vendor.id,building=coalesce(clean_building,building) where id=current_user_id;
  return jsonb_build_object('vendor_id',existing_vendor.id,'status',existing_vendor.status,'already_vendor',true);
 end if;
 insert into public.vendors(owner_id,name,category,building,status,email) values(current_user_id,clean_name,clean_category,clean_building,'pending',current_profile.email) returning * into new_vendor;
 update public.profiles set role='vendor',vendor_id=new_vendor.id,building=coalesce(clean_building,building) where id=current_user_id;
 return jsonb_build_object('vendor_id',new_vendor.id,'status',new_vendor.status,'already_vendor',false);
end $function$

CREATE OR REPLACE FUNCTION public.get_vendor_analytics(p_vendor_id uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; v_is_admin boolean:=coalesce((select private.is_admin()),false); v_current_vendor_id uuid:=(select private.current_vendor_id()); v_analytics_enabled boolean; v_from timestamptz; v_to timestamptz:=now();
begin
 if (select auth.uid()) is null then raise exception 'authentication required'; end if;
 if p_vendor_id is null then raise exception 'vendor id is required'; end if;
 if p_days is null or p_days<1 or p_days>366 then raise exception 'analytics period must be between 1 and 366 days'; end if;
 select v.analytics_enabled into v_analytics_enabled from public.vendors v where v.id=p_vendor_id;
 if not found then raise exception 'vendor not found'; end if;
 if not v_is_admin then
  if v_current_vendor_id is distinct from p_vendor_id then raise exception 'forbidden'; end if;
  if not coalesce(v_analytics_enabled,false) then raise exception 'growth analytics not enabled'; end if;
 end if;
 v_from:=v_to-make_interval(days=>p_days);
 select jsonb_build_object(
 'orders',count(so.id) filter(where so.status in('confirmed','accepted','preparing','ready','collected','completed')),
 'grossRevenue',coalesce(sum(so.subtotal) filter(where so.status in('confirmed','accepted','preparing','ready','collected','completed')),0),
 'platformCommission',coalesce(sum(so.subtotal*v.commission_rate) filter(where so.status in('confirmed','accepted','preparing','ready','collected','completed')),0),
 'vendorNet',coalesce(sum(so.subtotal*(1-v.commission_rate)) filter(where so.status in('confirmed','accepted','preparing','ready','collected','completed')),0),
 'averageOrderValue',coalesce(avg(so.subtotal) filter(where so.status in('confirmed','accepted','preparing','ready','collected','completed')),0),
 'completedOrders',count(so.id) filter(where so.status='completed'),'cancelledOrders',count(so.id) filter(where so.status='cancelled'),'periodFrom',v_from,'periodTo',v_to)
 into result from public.vendors v left join(public.order_suborders so join public.orders o on o.id=so.order_id and o.created_at>=v_from and o.created_at<v_to) on so.vendor_id=v.id where v.id=p_vendor_id group by v.id;
 return coalesce(result,jsonb_build_object('orders',0,'grossRevenue',0,'platformCommission',0,'vendorNet',0,'averageOrderValue',0,'completedOrders',0,'cancelledOrders',0,'periodFrom',v_from,'periodTo',v_to));
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_category_demand(p_days integer DEFAULT 28)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb;
begin
 if not (select private.is_admin()) then raise exception 'forbidden'; end if;
 if p_days<1 or p_days>366 then raise exception 'invalid period'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('category',category,'units',units,'revenue',revenue) order by units desc),'[]'::jsonb) into r
 from(select coalesce(m.category,'Other') category,sum(oi.qty)::bigint units,sum(oi.qty*oi.price)::numeric revenue
 from public.order_items oi join public.meals m on m.id=oi.meal_id join public.order_suborders so on so.id=oi.suborder_id join public.orders o on o.id=so.order_id
 where o.created_at>=now()-(p_days||' days')::interval and so.status in('confirmed','accepted','preparing','ready','collected','completed') group by 1)q;
 return r;
end $function$

CREATE OR REPLACE FUNCTION public.admin_reply_support_ticket(p_ticket_id uuid, p_body text, p_internal boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_message_id uuid;
begin
 if (select auth.uid()) is null or not coalesce((select private.is_admin()),false) then raise exception 'forbidden'; end if;
 if p_ticket_id is null or not exists(select 1 from public.support_tickets where id=p_ticket_id) then raise exception 'ticket not found'; end if;
 if length(btrim(coalesce(p_body,'')))<1 or length(btrim(p_body))>5000 then raise exception 'message must be between 1 and 5000 characters'; end if;
 insert into public.support_ticket_messages(ticket_id,sender_id,sender_role,body,internal) values(p_ticket_id,(select auth.uid()),'support',btrim(p_body),coalesce(p_internal,false)) returning id into v_message_id;
 update public.support_tickets set first_response_at=case when not coalesce(p_internal,false) then coalesce(first_response_at,now()) else first_response_at end,status=case when not coalesce(p_internal,false) and status='open'::public.support_status then 'waiting_customer'::public.support_status else status end,updated_at=now() where id=p_ticket_id;
 return v_message_id;
end $function$

CREATE OR REPLACE FUNCTION public.admin_update_support_ticket(p_ticket_id uuid, p_status support_status DEFAULT NULL::support_status, p_priority support_priority DEFAULT NULL::support_priority, p_assigned_to uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_ticket public.support_tickets%rowtype;
begin
 if (select auth.uid()) is null or not coalesce((select private.is_admin()),false) then raise exception 'forbidden'; end if;
 update public.support_tickets set status=coalesce(p_status,status),priority=coalesce(p_priority,priority),assigned_to=coalesce(p_assigned_to,assigned_to),resolved_at=case when p_status in ('resolved'::public.support_status,'closed'::public.support_status) then coalesce(resolved_at,now()) when p_status is not null then null else resolved_at end,updated_at=now() where id=p_ticket_id returning * into v_ticket;
 if not found then raise exception 'ticket not found'; end if;
 return jsonb_build_object('id',v_ticket.id,'ticketNumber',v_ticket.ticket_number,'status',v_ticket.status,'priority',v_ticket.priority,'assignedTo',v_ticket.assigned_to,'firstResponseAt',v_ticket.first_response_at,'resolvedAt',v_ticket.resolved_at,'updatedAt',v_ticket.updated_at);
end $function$

CREATE OR REPLACE FUNCTION private.order_customer_names(p_order_ids uuid[])
 RETURNS TABLE(order_id uuid, customer_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE caller uuid := auth.uid();
BEGIN
  IF caller IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=caller AND NOT p.suspended) THEN
    RAISE EXCEPTION 'An active signed-in account is required' USING ERRCODE='42501';
  END IF;
  IF cardinality(p_order_ids)>200 THEN RAISE EXCEPTION 'Request at most 200 orders'; END IF;
  RETURN QUERY SELECT o.id, COALESCE(NULLIF(btrim(p.name),''),NULLIF(btrim(o.guest_name),''),'Guest')
  FROM public.orders o LEFT JOIN public.profiles p ON p.id=o.customer_id
  WHERE o.id=ANY(p_order_ids) AND (
    o.customer_id=caller OR private.is_admin() OR EXISTS(
      SELECT 1 FROM public.order_suborders s JOIN public.vendors v ON v.id=s.vendor_id
      JOIN public.profiles owner_profile ON owner_profile.id=v.owner_id
      WHERE s.order_id=o.id AND v.owner_id=caller AND v.status='approved'
        AND owner_profile.role='vendor' AND NOT owner_profile.suspended
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_payfast_payment(p_order_id uuid, p_pf_payment_id text, p_m_payment_id text, p_amount_gross numeric, p_payment_status text, p_raw_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_log public.payfast_itn_log%ROWTYPE;
  v_sub record;
  v_fee numeric := 0;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
  IF v_order.payment_method<>'payfast' THEN RAISE EXCEPTION 'This is not a PayFast order'; END IF;
  IF nullif(trim(p_pf_payment_id),'') IS NULL OR p_m_payment_id IS DISTINCT FROM v_order.ticket_number THEN
    RAISE EXCEPTION 'Invalid PayFast payment reference';
  END IF;
  IF p_payment_status IS NULL THEN RAISE EXCEPTION 'Payment status is required'; END IF;
  IF p_amount_gross IS NULL OR p_amount_gross<>v_order.total THEN RAISE EXCEPTION 'PayFast amount does not match the order total'; END IF;
  SELECT * INTO v_log FROM public.payfast_itn_log WHERE pf_payment_id=p_pf_payment_id FOR UPDATE;
  IF FOUND THEN
    IF v_log.order_id IS DISTINCT FROM p_order_id THEN RAISE EXCEPTION 'Payment ID belongs to another order'; END IF;
    IF v_log.payment_status='COMPLETE' THEN RETURN jsonb_build_object('duplicate',true,'applied',false); END IF;
  END IF;
  IF coalesce(p_raw_payload->>'amount_fee','') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_fee:=abs((p_raw_payload->>'amount_fee')::numeric);
  END IF;
  INSERT INTO public.payfast_itn_log(pf_payment_id,order_id,m_payment_id,amount_gross,payment_status,raw_payload,processor_fee)
    VALUES(p_pf_payment_id,p_order_id,p_m_payment_id,p_amount_gross,p_payment_status,coalesce(p_raw_payload,'{}'::jsonb),v_fee)
    ON CONFLICT(pf_payment_id) DO UPDATE SET payment_status=excluded.payment_status,
      raw_payload=excluded.raw_payload,amount_gross=excluded.amount_gross,
      processor_fee=excluded.processor_fee,processed_at=now()
      WHERE public.payfast_itn_log.order_id=excluded.order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment ID belongs to another order'; END IF;
  IF p_payment_status<>'COMPLETE' THEN
    RETURN jsonb_build_object('duplicate',false,'applied',false,'reason','not_complete');
  END IF;
  IF v_order.status NOT IN ('pending_payment','payment_submitted') THEN
    RETURN jsonb_build_object('duplicate',false,'applied',false,'reason','not_eligible','current_status',v_order.status);
  END IF;
  UPDATE public.orders SET status='confirmed' WHERE id=p_order_id;
  UPDATE public.order_suborders SET status='confirmed',payment_status='paid' WHERE order_id=p_order_id;
  IF v_order.customer_id IS NOT NULL THEN
    INSERT INTO public.notifications(user_id,type,title,body,action_url)
      VALUES(v_order.customer_id,'payment_confirmed','Payment confirmed',
        format('Your payment for %s has been verified.',v_order.ticket_number),'/orders/'||p_order_id::text);
  END IF;
  FOR v_sub IN SELECT so.subtotal,v.owner_id,v.name FROM public.order_suborders so
    JOIN public.vendors v ON v.id=so.vendor_id WHERE so.order_id=p_order_id
  LOOP
    IF v_sub.owner_id IS NOT NULL THEN
      INSERT INTO public.notifications(user_id,type,title,body,action_url)
        VALUES(v_sub.owner_id,'new_order','New paid order '||v_order.ticket_number,
          format('%s: R%s for %s',v_sub.name,v_sub.subtotal,to_char(v_order.delivery_date,'DD Mon YYYY')),'/vendor/orders');
    END IF;
  END LOOP;
  RETURN jsonb_build_object('duplicate',false,'applied',true,
    'order',(SELECT public.order_to_json(o) FROM public.orders o WHERE o.id=p_order_id));
END $function$

CREATE OR REPLACE FUNCTION public.create_support_ticket(p_subject text, p_category text, p_body text, p_requester_name text, p_requester_email text, p_requester_contact text, p_order_id uuid DEFAULT NULL::uuid, p_meta jsonb DEFAULT '{}'::jsonb, p_attachment_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE caller uuid:=auth.uid(); ticket public.support_tickets%rowtype; message public.support_ticket_messages%rowtype;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'Please sign in before contacting support' USING ERRCODE='42501'; END IF;
  IF length(btrim(coalesce(p_subject,''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Subject must be between 1 and 200 characters'; END IF;
  IF length(btrim(coalesce(p_body,''))) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'Message must be between 1 and 5000 characters'; END IF;
  IF p_attachment_path IS NOT NULL AND split_part(p_attachment_path,'/',1)<>caller::text THEN
    RAISE EXCEPTION 'Attachment must belong to the requester' USING ERRCODE='42501';
  END IF;
  INSERT INTO public.support_tickets(requester_id,requester_name,requester_email,requester_contact,subject,category,order_id,meta,attachment_url)
  VALUES(caller,coalesce(nullif(btrim(p_requester_name),''),'Customer'),nullif(btrim(p_requester_email),''),nullif(btrim(p_requester_contact),''),btrim(p_subject),p_category,p_order_id,coalesce(p_meta,'{}'::jsonb),p_attachment_path)
  RETURNING * INTO ticket;
  INSERT INTO public.support_ticket_messages(ticket_id,sender_id,sender_role,body,internal)
  VALUES(ticket.id,caller,'customer',btrim(p_body),false) RETURNING * INTO message;
  RETURN to_jsonb(ticket) || jsonb_build_object('support_ticket_messages',jsonb_build_array(to_jsonb(message)));
END;
$function$
